/** A local dataset's manifest is generated by the authenticated data bridge.
 * Never probe root files that are not advertised. Hub datasets retain the
 * upstream's optional-file discovery behavior. */
export function platformProgressCandidates(
  repoId: string,
  candidates: readonly string[],
  available: unknown,
): readonly string[] {
  if (!repoId.startsWith("local/")) return candidates;
  if (!Array.isArray(available)) return [];
  const files = new Set(available.filter((value) => typeof value === "string"));
  return candidates.filter((name) => files.has(name));
}
